-- OPTIONAL SEED — not a migration. Nothing runs this for you.
--
-- Puts the two sample papers into the portal as real `tests` rows: the Word and
-- Excel practicals that used to exist only as TypeScript fixtures
-- (`src/exam/seedAttempt.ts`, `src/exam/excelSeedAttempt.ts`), which the exam
-- player still falls back to when no paper has been authored.
--
-- It lives in `db/seeds/` rather than `db/migrations/` because it is content,
-- not schema. A migration has to run on every database or the code breaks
-- against it; this is thirty questions of demo data that most databases have no
-- reason to want. See `db/seeds/README.md` for how to run it and when you would.
--
-- Generated from those fixtures rather than typed by hand, and checked on the
-- way out: the rows below rebuild both papers question for question.
--
-- Safe to run more than once, and safe on an empty database:
--   * no exam yet          -> does nothing, says so
--   * papers already there -> does nothing, says so
--   * otherwise            -> attaches them to the oldest exam
--
-- To undo:
--   DELETE FROM tests WHERE slug IN ('word-practical-sample', 'excel-practical-sample');
--   (test_questions cascades.)

DO $seed$
DECLARE
  target_exam uuid;
BEGIN
  SELECT id INTO target_exam FROM exams ORDER BY created_at LIMIT 1;

  IF target_exam IS NULL THEN
    RAISE NOTICE 'No exam exists yet — sample papers not seeded.';
    RETURN;
  END IF;

  IF EXISTS (SELECT 1 FROM tests WHERE slug IN ('word-practical-sample', 'excel-practical-sample')) THEN
    RAISE NOTICE 'Sample papers are already present — nothing to do.';
    RETURN;
  END IF;

  INSERT INTO tests
    (id, exam_id, name, slug, subject, description, section_name, tagline, duration_minutes, qualifying_marks, status)
  VALUES
    ('ae238f44-6cc5-48b7-a991-daf82ea70f79', target_exam, 'Word Practical — Sample Paper', 'word-practical-sample', 'word',
     'The original sample Word paper, seeded from the fixture it used to live in.',
     'Word Processing', 'Your Progress Brings You Closer to Success', 10, 13, 'published'),
    ('d6c49655-3d70-47bd-bc90-fca05effdffc', target_exam, 'Excel Practical — Sample Paper', 'excel-practical-sample', 'excel',
     'The original sample Excel paper, seeded from the fixture it used to live in.',
     'Spreadsheet', 'Your Progress Brings You Closer to Success', 15, 13, 'published');

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('93b82180-12d6-453f-aaa5-64c971a90fa9', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 1, 'word', 'Character Formatting', 'Easy', 4,
    'Make the paragraph bold and underline it.', 'पैराग्राफ को बोल्ड करें, अंडरलाइन करें।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'On the Home tab, in the Font group, click Bold (B).', 'Click Underline (U) in the same group.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Home टैब के Font ग्रुप में Bold (B) पर क्लिक करें।', 'उसी ग्रुप में Underline (U) पर क्लिक करें।']::text[],
    '{"subject":"word","lines":{"en":["The afternoon drifted quietly across the town, carrying warm air through half-open windows and stirring the pages of an unfinished notebook. Somewhere beyond the old market, a bicycle bell rang twice, followed by the distant sound of a bus turning around the corner. Nobody seemed to be in a hurry. A shopkeeper arranged blue bottles on a wooden shelf, while a curious cat watched from beneath a parked scooter. In the nearby park, children invented complicated rules for a game that had no name, arguing loudly before laughing and starting again. Above them, clouds gathered like scattered pieces of paper, changing shape whenever the wind moved. On a rooftop, someone watered a row of small plants and checked the sky with hopeful eyes. The city continued its ordinary rhythm: phones buzzed, doors opened, cups clinked, and footsteps crossed dusty sidewalks. Yet for a few minutes, everything felt strangely peaceful. Perhaps quiet moments are easier to notice when nothing important is expected to happen. A forgotten coin, a cracked sign, a yellow flower growing beside a wall—small things can become memorable when attention slows down. By evening, the streets would become brighter, louder, and busier, but for now the town simply breathed beneath the pale afternoon sun, waiting for whatever tomorrow decided to bring."],"hi":["The afternoon drifted quietly across the town, carrying warm air through half-open windows and stirring the pages of an unfinished notebook. Somewhere beyond the old market, a bicycle bell rang twice, followed by the distant sound of a bus turning around the corner. Nobody seemed to be in a hurry. A shopkeeper arranged blue bottles on a wooden shelf, while a curious cat watched from beneath a parked scooter. In the nearby park, children invented complicated rules for a game that had no name, arguing loudly before laughing and starting again. Above them, clouds gathered like scattered pieces of paper, changing shape whenever the wind moved. On a rooftop, someone watered a row of small plants and checked the sky with hopeful eyes. The city continued its ordinary rhythm: phones buzzed, doors opened, cups clinked, and footsteps crossed dusty sidewalks. Yet for a few minutes, everything felt strangely peaceful. Perhaps quiet moments are easier to notice when nothing important is expected to happen. A forgotten coin, a cracked sign, a yellow flower growing beside a wall—small things can become memorable when attention slows down. By evening, the streets would become brighter, louder, and busier, but for now the town simply breathed beneath the pale afternoon sun, waiting for whatever tomorrow decided to bring."]},"scope":"all"}'::jsonb, '[{"kind":"bold"},{"kind":"underline"}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('cdb34609-e913-4d08-971e-b053d4129ae6', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 2, 'word', 'Text Highlight', 'Easy', 3,
    'Highlight the paragraph with green color.', 'पैराग्राफ को हरे रंग से हाइलाइट करें।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'In the Font group, open the arrow beside Text Highlight Colour.', 'Pick the bright green swatch — the second colour in the top row.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Font ग्रुप में Text Highlight Colour के बगल वाले तीर को खोलें।', 'चमकीला हरा स्वैच चुनें — ऊपर की पंक्ति का दूसरा रंग।']::text[],
    '{"subject":"word","lines":{"en":["Rain arrived without warning just after lunch, tapping softly against windows and turning the dusty road outside into a ribbon of silver. People hurried beneath umbrellas, while a few stood under shop awnings waiting for the clouds to pass. An old man carried a paper bag filled with vegetables, carefully balancing it beneath his coat. Across the street, a dog shook water from its fur and looked offended by the weather. Inside a small café, three friends continued their conversation as though the storm were part of the furniture. Steam rose from cups of tea, and someone played a quiet song from a phone near the counter. The rain became heavier for a while, covering every other sound in the neighborhood. Then, almost as suddenly as it had begun, it weakened. The clouds opened slightly, allowing a thin beam of sunlight to fall across the wet pavement. Cars moved again, bicycles appeared, and the street slowly returned to its usual rhythm. Nobody remembered exactly what they had been rushing toward, but everyone seemed happier to be moving again."],"hi":["Rain arrived without warning just after lunch, tapping softly against windows and turning the dusty road outside into a ribbon of silver. People hurried beneath umbrellas, while a few stood under shop awnings waiting for the clouds to pass. An old man carried a paper bag filled with vegetables, carefully balancing it beneath his coat. Across the street, a dog shook water from its fur and looked offended by the weather. Inside a small café, three friends continued their conversation as though the storm were part of the furniture. Steam rose from cups of tea, and someone played a quiet song from a phone near the counter. The rain became heavier for a while, covering every other sound in the neighborhood. Then, almost as suddenly as it had begun, it weakened. The clouds opened slightly, allowing a thin beam of sunlight to fall across the wet pavement. Cars moved again, bicycles appeared, and the street slowly returned to its usual rhythm. Nobody remembered exactly what they had been rushing toward, but everyone seemed happier to be moving again."]},"scope":"all"}'::jsonb, '[{"kind":"highlight","color":"#00ff00"}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('d8f8568c-0aa5-4eb3-a7ce-862d5bc52c60', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 3, 'word', 'Font', 'Easy', 3,
    'Set the font of the paragraph to Times New Roman.', 'पैराग्राफ का फॉन्ट टाइम्स न्यू रोमन में सेट करें।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'Open the Font name box in the Font group.', 'Choose Times New Roman from the list.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Font ग्रुप में Font name बॉक्स खोलें।', 'सूची में से Times New Roman चुनें।']::text[],
    '{"subject":"word","lines":{"en":["At the edge of the village stood a wooden house with a green door and a garden full of plants that seemed determined to grow in every direction. Nobody knew exactly how old the house was, although the oldest residents claimed that their grandparents had played near it as children. Every morning, a woman named Mira opened the windows, swept the front steps, and placed a small bowl of water beside the gate for passing animals. Birds often landed on the fence, and occasionally a sleepy dog wandered into the garden and refused to leave. The house was quiet except for the ticking clock in the hallway and the occasional creak of the wooden floor. In the evenings, neighbors gathered outside to exchange stories about weather, crops, distant relatives, and strange things they had seen on the road. Nothing particularly exciting happened, yet nobody seemed disappointed. Life there moved according to familiar patterns, and those patterns gave ordinary days a comfortable shape. When the sun disappeared behind the hills, the garden became dark and still, while the green door reflected the warm glow of a lamp inside."],"hi":["At the edge of the village stood a wooden house with a green door and a garden full of plants that seemed determined to grow in every direction. Nobody knew exactly how old the house was, although the oldest residents claimed that their grandparents had played near it as children. Every morning, a woman named Mira opened the windows, swept the front steps, and placed a small bowl of water beside the gate for passing animals. Birds often landed on the fence, and occasionally a sleepy dog wandered into the garden and refused to leave. The house was quiet except for the ticking clock in the hallway and the occasional creak of the wooden floor. In the evenings, neighbors gathered outside to exchange stories about weather, crops, distant relatives, and strange things they had seen on the road. Nothing particularly exciting happened, yet nobody seemed disappointed. Life there moved according to familiar patterns, and those patterns gave ordinary days a comfortable shape. When the sun disappeared behind the hills, the garden became dark and still, while the green door reflected the warm glow of a lamp inside."]},"scope":"all"}'::jsonb, '[{"kind":"fontFamily","family":"Times New Roman"}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('e5f8003d-0a8d-49d6-9b60-1cd5896b4341', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 4, 'word', 'Font Size', 'Medium', 3,
    'Set the font size of the paragraph to 15.', 'पैराग्राफ का फॉन्ट साइज 15 में सेट करें।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'Click inside the Font Size box in the Font group.', 'Type 15 and press Enter. 15 is not on the drop-down list, so it has to be typed.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Font ग्रुप के Font Size बॉक्स में क्लिक करें।', '15 टाइप करके Enter दबाएँ। 15 ड्रॉप-डाउन सूची में नहीं है, इसलिए इसे टाइप करना ज़रूरी है।']::text[],
    '{"subject":"word","lines":{"en":["The train station was almost empty when the clock reached seven. A cleaner pushed a cart slowly along the platform, humming a tune that disappeared beneath the noise of an arriving train. A young traveler sat on a bench with a backpack between his feet and a folded map in his hands. He had changed his destination three times already and still was not completely sure where he wanted to go. Across the tracks, a woman read a newspaper while drinking coffee from a paper cup. The loudspeaker announced a delay, followed by a second announcement correcting the first one. Nobody reacted with surprise. Trains, like people, apparently had their own ideas about schedules. After twenty minutes, the traveler stood, stretched his legs, and looked toward the dark end of the platform. A small light appeared in the distance and slowly grew brighter. The train arrived with a long metallic sigh. Doors opened, passengers stepped out, and others climbed aboard. For a moment, the station became crowded and noisy. Then the doors closed, the train moved away, and silence returned as if nothing had happened."],"hi":["The train station was almost empty when the clock reached seven. A cleaner pushed a cart slowly along the platform, humming a tune that disappeared beneath the noise of an arriving train. A young traveler sat on a bench with a backpack between his feet and a folded map in his hands. He had changed his destination three times already and still was not completely sure where he wanted to go. Across the tracks, a woman read a newspaper while drinking coffee from a paper cup. The loudspeaker announced a delay, followed by a second announcement correcting the first one. Nobody reacted with surprise. Trains, like people, apparently had their own ideas about schedules. After twenty minutes, the traveler stood, stretched his legs, and looked toward the dark end of the platform. A small light appeared in the distance and slowly grew brighter. The train arrived with a long metallic sigh. Doors opened, passengers stepped out, and others climbed aboard. For a moment, the station became crowded and noisy. Then the doors closed, the train moved away, and silence returned as if nothing had happened."]},"scope":"all"}'::jsonb, '[{"kind":"fontSize","size":15}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('6af55800-f744-4087-83b0-fe60e0b1df65', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 5, 'word', 'Paragraph Alignment', 'Easy', 3,
    'Apply center alignment to the paragraph.', 'पैराग्राफ में सेंटर अलाइनमेंट अप्लाई करें।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'On the Home tab, in the Paragraph group, click Center.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Home टैब के Paragraph ग्रुप में Center पर क्लिक करें।']::text[],
    '{"subject":"word","lines":{"en":["Somewhere in the middle of a crowded city was a narrow street that seemed to have been forgotten by modern time. The buildings were tall but slightly uneven, with balconies covered by plants and windows painted in colors that had faded over the years. A bakery occupied the corner, filling the street with the smell of fresh bread every morning. Next door was a tiny repair shop where the owner fixed watches, radios, lamps, and almost anything else people brought through the door. A handwritten sign in the window simply said, “If it can be repaired, bring it here.” Nobody knew whether the statement was completely true, but people liked the confidence behind it. At noon, delivery workers stopped for sandwiches, students bought pastries, and elderly residents sat on benches discussing the latest neighborhood rumors. By sunset, the street became quieter. Lights appeared behind curtains, the bakery closed its doors, and the repair shop owner finally turned off his desk lamp. The city remained noisy beyond the corner, but this little street seemed to exist at its own pace."],"hi":["Somewhere in the middle of a crowded city was a narrow street that seemed to have been forgotten by modern time. The buildings were tall but slightly uneven, with balconies covered by plants and windows painted in colors that had faded over the years. A bakery occupied the corner, filling the street with the smell of fresh bread every morning. Next door was a tiny repair shop where the owner fixed watches, radios, lamps, and almost anything else people brought through the door. A handwritten sign in the window simply said, “If it can be repaired, bring it here.” Nobody knew whether the statement was completely true, but people liked the confidence behind it. At noon, delivery workers stopped for sandwiches, students bought pastries, and elderly residents sat on benches discussing the latest neighborhood rumors. By sunset, the street became quieter. Lights appeared behind curtains, the bakery closed its doors, and the repair shop owner finally turned off his desk lamp. The city remained noisy beyond the corner, but this little street seemed to exist at its own pace."]},"scope":"all"}'::jsonb, '[{"kind":"align","align":"center"}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('4f868c63-a848-4c69-823f-c08e298d99a3', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 6, 'word', 'Line Spacing', 'Medium', 4,
    'Set the line spacing of the paragraph to 2.0.', 'पैराग्राफ में लाइन स्पेसिंग 2.0 करें।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'In the Paragraph group, open the Line Spacing menu.', 'Choose 2.0.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Paragraph ग्रुप में Line Spacing मेन्यू खोलें।', '2.0 चुनें।']::text[],
    '{"subject":"word","lines":{"en":["The notebook had been sitting inside the drawer for years, hidden beneath old receipts, broken pencils, and a collection of keys nobody could identify. Its cover was brown and scratched, with a tiny star drawn near one corner. When it was finally opened, the first few pages contained shopping lists and reminders about appointments. Later pages were filled with sketches, unfinished sentences, random numbers, and descriptions of places that no longer existed. There was a drawing of a house beside a lake, although nobody remembered owning a house near a lake. Another page described a blue bicycle, a red umbrella, and a mysterious bird that appeared every Thursday. The writing became less organized toward the end, but somehow more interesting. One sentence simply said, “Remember that ordinary days are not ordinary while they are happening.” The person reading it stopped for a moment. Outside, traffic moved along the road, someone laughed in the hallway, and a pressure cooker whistled in a nearby kitchen. Nothing unusual was happening. Yet the sentence made the familiar world feel slightly different, as though every small detail had been waiting quietly to be noticed."],"hi":["The notebook had been sitting inside the drawer for years, hidden beneath old receipts, broken pencils, and a collection of keys nobody could identify. Its cover was brown and scratched, with a tiny star drawn near one corner. When it was finally opened, the first few pages contained shopping lists and reminders about appointments. Later pages were filled with sketches, unfinished sentences, random numbers, and descriptions of places that no longer existed. There was a drawing of a house beside a lake, although nobody remembered owning a house near a lake. Another page described a blue bicycle, a red umbrella, and a mysterious bird that appeared every Thursday. The writing became less organized toward the end, but somehow more interesting. One sentence simply said, “Remember that ordinary days are not ordinary while they are happening.” The person reading it stopped for a moment. Outside, traffic moved along the road, someone laughed in the hallway, and a pressure cooker whistled in a nearby kitchen. Nothing unusual was happening. Yet the sentence made the familiar world feel slightly different, as though every small detail had been waiting quietly to be noticed."]},"scope":"all"}'::jsonb, '[{"kind":"lineHeight","value":2}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('ded78d11-7ac6-4e81-aeab-9425ff74369f', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 7, 'word', 'Paragraph Indent', 'Medium', 3,
    'Increase the indent level of the paragraph by one level.', 'पैराग्राफ के इंडेंट को एक लेवल बढ़ाएं।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'In the Paragraph group, click Increase Indent once.', 'One click is one level; a second click indents too far.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Paragraph ग्रुप में Increase Indent पर एक बार क्लिक करें।', 'एक क्लिक एक लेवल है; दूसरा क्लिक ज़्यादा इंडेंट कर देगा।']::text[],
    '{"subject":"word","lines":{"en":["The library closed at eight, but at seven fifty-five the building still contained a surprising amount of activity. Students hurried between shelves searching for final references, a professor typed notes at a corner desk, and two children whispered loudly enough to attract repeated warnings from their mother. Near the entrance, an old clock made a soft clicking sound every second. The librarian walked through the aisles, returning books to their places with the patience of someone who had performed the same task thousands of times. Outside, evening traffic had begun to glow beneath streetlights. Inside, the smell of paper and dust made the building feel separate from the city. At exactly eight, the librarian announced closing time. Chairs moved, bags were lifted, and books were carefully packed away. One student remained seated for a few extra seconds, staring at a page without reading it. Then she closed the book and smiled. She had not finished everything she planned to do, but perhaps that was acceptable. Some days were meant for completing tasks, while others were simply meant for making progress."],"hi":["The library closed at eight, but at seven fifty-five the building still contained a surprising amount of activity. Students hurried between shelves searching for final references, a professor typed notes at a corner desk, and two children whispered loudly enough to attract repeated warnings from their mother. Near the entrance, an old clock made a soft clicking sound every second. The librarian walked through the aisles, returning books to their places with the patience of someone who had performed the same task thousands of times. Outside, evening traffic had begun to glow beneath streetlights. Inside, the smell of paper and dust made the building feel separate from the city. At exactly eight, the librarian announced closing time. Chairs moved, bags were lifted, and books were carefully packed away. One student remained seated for a few extra seconds, staring at a page without reading it. Then she closed the book and smiled. She had not finished everything she planned to do, but perhaps that was acceptable. Some days were meant for completing tasks, while others were simply meant for making progress."]},"scope":"all"}'::jsonb, '[{"kind":"indent","levels":1}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('f97fa0c5-3c70-4389-b689-7afd4e43b7c3', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 8, 'word', 'Line Selection', 'Hard', 4,
    'Underline the 2nd line of the document.', 'डॉक्यूमेंट की 2वीं लाइन को अंडरलाइन करें।',
    ARRAY['Drag across the second line of the paragraph — the line that begins “had used it”.', 'In the Font group, click Underline (U).', 'Leave the rest of the passage untouched.']::text[], ARRAY['पैराग्राफ की दूसरी लाइन पर ड्रैग करें — वह लाइन जो “had used it” से शुरू होती है।', 'Font ग्रुप में Underline (U) पर क्लिक करें।', 'बाकी पैराग्राफ को वैसा ही छोड़ दें।']::text[],
    '{"subject":"word","lines":{"en":["A small boat rested on the shore, its wooden sides covered with layers of old paint. Nobody had used it since the previous summer, but every morning someone checked the ropes and moved it slightly above the reach of the waves. The sea was unusually calm that day. Far away, a group of birds moved together across the horizon, changing direction whenever the wind shifted. A boy walked along the beach collecting shells and pieces of smooth glass. He placed each discovery carefully into a blue bucket, although he had no plan for what to do with them later. His grandfather sat nearby beneath a faded umbrella and watched without saying much. Occasionally he pointed toward something floating in the water, and the boy would run closer to investigate. By afternoon, the bucket was nearly full. The boy looked at his collection proudly, then suddenly decided that he liked the beach better without it. One by one, he returned the shells to the sand. The glass pieces stayed in his pocket. Some things, he decided, were worth keeping."],"hi":["A small boat rested on the shore, its wooden sides covered with layers of old paint. Nobody had used it since the previous summer, but every morning someone checked the ropes and moved it slightly above the reach of the waves. The sea was unusually calm that day. Far away, a group of birds moved together across the horizon, changing direction whenever the wind shifted. A boy walked along the beach collecting shells and pieces of smooth glass. He placed each discovery carefully into a blue bucket, although he had no plan for what to do with them later. His grandfather sat nearby beneath a faded umbrella and watched without saying much. Occasionally he pointed toward something floating in the water, and the boy would run closer to investigate. By afternoon, the bucket was nearly full. The boy looked at his collection proudly, then suddenly decided that he liked the beach better without it. One by one, he returned the shells to the sand. The glass pieces stayed in his pocket. Some things, he decided, were worth keeping."]},"scope":{"from":92,"to":178}}'::jsonb, '[{"kind":"underline"}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('f3506484-813f-49da-9512-80d183f43f03', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 9, 'word', 'Font Size', 'Easy', 3,
    'Set the font size of the paragraph to 8.', 'पैराग्राफ का फॉन्ट साइज 8 में सेट करें।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'Open the Font Size box in the Font group and choose 8.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Font ग्रुप में Font Size बॉक्स खोलकर 8 चुनें।']::text[],
    '{"subject":"word","lines":{"en":["The train station was almost empty when the clock reached seven. A cleaner pushed a cart slowly along the platform, humming a tune that disappeared beneath the noise of an arriving train. A young traveler sat on a bench with a backpack between his feet and a folded map in his hands. He had changed his destination three times already and still was not completely sure where he wanted to go. Across the tracks, a woman read a newspaper while drinking coffee from a paper cup. The loudspeaker announced a delay, followed by a second announcement correcting the first one. Nobody reacted with surprise. Trains, like people, apparently had their own ideas about schedules. After twenty minutes, the traveler stood, stretched his legs, and looked toward the dark end of the platform. A small light appeared in the distance and slowly grew brighter. The train arrived with a long metallic sigh. Doors opened, passengers stepped out, and others climbed aboard. For a moment, the station became crowded and noisy. Then the doors closed, the train moved away, and silence returned as if nothing had happened."],"hi":["The train station was almost empty when the clock reached seven. A cleaner pushed a cart slowly along the platform, humming a tune that disappeared beneath the noise of an arriving train. A young traveler sat on a bench with a backpack between his feet and a folded map in his hands. He had changed his destination three times already and still was not completely sure where he wanted to go. Across the tracks, a woman read a newspaper while drinking coffee from a paper cup. The loudspeaker announced a delay, followed by a second announcement correcting the first one. Nobody reacted with surprise. Trains, like people, apparently had their own ideas about schedules. After twenty minutes, the traveler stood, stretched his legs, and looked toward the dark end of the platform. A small light appeared in the distance and slowly grew brighter. The train arrived with a long metallic sigh. Doors opened, passengers stepped out, and others climbed aboard. For a moment, the station became crowded and noisy. Then the doors closed, the train moved away, and silence returned as if nothing had happened."]},"scope":"all"}'::jsonb, '[{"kind":"fontSize","size":8}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('305d3c42-f50a-468a-9f62-0865e8d725a6', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 10, 'word', 'Paragraph Alignment', 'Easy', 3,
    'Apply justify alignment to the paragraph.', 'पैराग्राफ में justify अलाइनमेंट अप्लाई करें।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'On the Home tab, in the Paragraph group, click Justify.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Home टैब के Paragraph ग्रुप में Justify पर क्लिक करें।']::text[],
    '{"subject":"word","lines":{"en":["Somewhere in the middle of a crowded city was a narrow street that seemed to have been forgotten by modern time. The buildings were tall but slightly uneven, with balconies covered by plants and windows painted in colors that had faded over the years. A bakery occupied the corner, filling the street with the smell of fresh bread every morning. Next door was a tiny repair shop where the owner fixed watches, radios, lamps, and almost anything else people brought through the door. A handwritten sign in the window simply said, “If it can be repaired, bring it here.” Nobody knew whether the statement was completely true, but people liked the confidence behind it. At noon, delivery workers stopped for sandwiches, students bought pastries, and elderly residents sat on benches discussing the latest neighborhood rumors. By sunset, the street became quieter. Lights appeared behind curtains, the bakery closed its doors, and the repair shop owner finally turned off his desk lamp. The city remained noisy beyond the corner, but this little street seemed to exist at its own pace."],"hi":["Somewhere in the middle of a crowded city was a narrow street that seemed to have been forgotten by modern time. The buildings were tall but slightly uneven, with balconies covered by plants and windows painted in colors that had faded over the years. A bakery occupied the corner, filling the street with the smell of fresh bread every morning. Next door was a tiny repair shop where the owner fixed watches, radios, lamps, and almost anything else people brought through the door. A handwritten sign in the window simply said, “If it can be repaired, bring it here.” Nobody knew whether the statement was completely true, but people liked the confidence behind it. At noon, delivery workers stopped for sandwiches, students bought pastries, and elderly residents sat on benches discussing the latest neighborhood rumors. By sunset, the street became quieter. Lights appeared behind curtains, the bakery closed its doors, and the repair shop owner finally turned off his desk lamp. The city remained noisy beyond the corner, but this little street seemed to exist at its own pace."]},"scope":"all"}'::jsonb, '[{"kind":"align","align":"justify"}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('af37aef4-5fcc-4239-be3c-256d5bde984d', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 11, 'word', 'Font', 'Easy', 3,
    'Set the font of the paragraph to Calibri.', 'पैराग्राफ का फॉन्ट Calibri में सेट करें।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'Open the Font name box in the Font group.', 'Choose Calibri. It has to be chosen, not left as the default.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Font ग्रुप में Font name बॉक्स खोलें।', 'Calibri चुनें। इसे चुनना ज़रूरी है, डिफ़ॉल्ट पर छोड़ना काफी नहीं है।']::text[],
    '{"subject":"word","lines":{"en":["At the edge of the village stood a wooden house with a green door and a garden full of plants that seemed determined to grow in every direction. Nobody knew exactly how old the house was, although the oldest residents claimed that their grandparents had played near it as children. Every morning, a woman named Mira opened the windows, swept the front steps, and placed a small bowl of water beside the gate for passing animals. Birds often landed on the fence, and occasionally a sleepy dog wandered into the garden and refused to leave. The house was quiet except for the ticking clock in the hallway and the occasional creak of the wooden floor. In the evenings, neighbors gathered outside to exchange stories about weather, crops, distant relatives, and strange things they had seen on the road. Nothing particularly exciting happened, yet nobody seemed disappointed. Life there moved according to familiar patterns, and those patterns gave ordinary days a comfortable shape. When the sun disappeared behind the hills, the garden became dark and still, while the green door reflected the warm glow of a lamp inside."],"hi":["At the edge of the village stood a wooden house with a green door and a garden full of plants that seemed determined to grow in every direction. Nobody knew exactly how old the house was, although the oldest residents claimed that their grandparents had played near it as children. Every morning, a woman named Mira opened the windows, swept the front steps, and placed a small bowl of water beside the gate for passing animals. Birds often landed on the fence, and occasionally a sleepy dog wandered into the garden and refused to leave. The house was quiet except for the ticking clock in the hallway and the occasional creak of the wooden floor. In the evenings, neighbors gathered outside to exchange stories about weather, crops, distant relatives, and strange things they had seen on the road. Nothing particularly exciting happened, yet nobody seemed disappointed. Life there moved according to familiar patterns, and those patterns gave ordinary days a comfortable shape. When the sun disappeared behind the hills, the garden became dark and still, while the green door reflected the warm glow of a lamp inside."]},"scope":"all"}'::jsonb, '[{"kind":"fontFamily","family":"Calibri"}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('e83aa40a-d5b3-4ed8-8cd0-a2e3e62231bf', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 12, 'word', 'Character Formatting', 'Easy', 4,
    'Make the paragraph bold and italic it.', 'पैराग्राफ को बोल्ड करें, italic करें।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'On the Home tab, in the Font group, click Bold (B).', 'Click Italic (I) in the same group.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Home टैब के Font ग्रुप में Bold (B) पर क्लिक करें।', 'उसी ग्रुप में Italic (I) पर क्लिक करें।']::text[],
    '{"subject":"word","lines":{"en":["The afternoon drifted quietly across the town, carrying warm air through half-open windows and stirring the pages of an unfinished notebook. Somewhere beyond the old market, a bicycle bell rang twice, followed by the distant sound of a bus turning around the corner. Nobody seemed to be in a hurry. A shopkeeper arranged blue bottles on a wooden shelf, while a curious cat watched from beneath a parked scooter. In the nearby park, children invented complicated rules for a game that had no name, arguing loudly before laughing and starting again. Above them, clouds gathered like scattered pieces of paper, changing shape whenever the wind moved. On a rooftop, someone watered a row of small plants and checked the sky with hopeful eyes. The city continued its ordinary rhythm: phones buzzed, doors opened, cups clinked, and footsteps crossed dusty sidewalks. Yet for a few minutes, everything felt strangely peaceful. Perhaps quiet moments are easier to notice when nothing important is expected to happen. A forgotten coin, a cracked sign, a yellow flower growing beside a wall—small things can become memorable when attention slows down. By evening, the streets would become brighter, louder, and busier, but for now the town simply breathed beneath the pale afternoon sun, waiting for whatever tomorrow decided to bring."],"hi":["The afternoon drifted quietly across the town, carrying warm air through half-open windows and stirring the pages of an unfinished notebook. Somewhere beyond the old market, a bicycle bell rang twice, followed by the distant sound of a bus turning around the corner. Nobody seemed to be in a hurry. A shopkeeper arranged blue bottles on a wooden shelf, while a curious cat watched from beneath a parked scooter. In the nearby park, children invented complicated rules for a game that had no name, arguing loudly before laughing and starting again. Above them, clouds gathered like scattered pieces of paper, changing shape whenever the wind moved. On a rooftop, someone watered a row of small plants and checked the sky with hopeful eyes. The city continued its ordinary rhythm: phones buzzed, doors opened, cups clinked, and footsteps crossed dusty sidewalks. Yet for a few minutes, everything felt strangely peaceful. Perhaps quiet moments are easier to notice when nothing important is expected to happen. A forgotten coin, a cracked sign, a yellow flower growing beside a wall—small things can become memorable when attention slows down. By evening, the streets would become brighter, louder, and busier, but for now the town simply breathed beneath the pale afternoon sun, waiting for whatever tomorrow decided to bring."]},"scope":"all"}'::jsonb, '[{"kind":"bold"},{"kind":"italic"}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('b1c3a35f-2921-4fbe-97e7-6507ca6021f5', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 13, 'word', 'Line Selection', 'Hard', 4,
    'Red colour highlight the 2nd line of the document.', 'डॉक्यूमेंट की 2वीं लाइन को red colour highlight करें।',
    ARRAY['Drag across the second line of the paragraph — the line that begins “had used it”.', 'In the Font group, open the arrow beside Text Highlight Colour.', 'Pick red — the first colour in the second row.']::text[], ARRAY['पैराग्राफ की दूसरी लाइन पर ड्रैग करें — वह लाइन जो “had used it” से शुरू होती है।', 'Font ग्रुप में Text Highlight Colour के बगल वाले तीर को खोलें।', 'लाल चुनें — दूसरी पंक्ति का पहला रंग।']::text[],
    '{"subject":"word","lines":{"en":["A small boat rested on the shore, its wooden sides covered with layers of old paint. Nobody had used it since the previous summer, but every morning someone checked the ropes and moved it slightly above the reach of the waves. The sea was unusually calm that day. Far away, a group of birds moved together across the horizon, changing direction whenever the wind shifted. A boy walked along the beach collecting shells and pieces of smooth glass. He placed each discovery carefully into a blue bucket, although he had no plan for what to do with them later. His grandfather sat nearby beneath a faded umbrella and watched without saying much. Occasionally he pointed toward something floating in the water, and the boy would run closer to investigate. By afternoon, the bucket was nearly full. The boy looked at his collection proudly, then suddenly decided that he liked the beach better without it. One by one, he returned the shells to the sand. The glass pieces stayed in his pocket. Some things, he decided, were worth keeping."],"hi":["A small boat rested on the shore, its wooden sides covered with layers of old paint. Nobody had used it since the previous summer, but every morning someone checked the ropes and moved it slightly above the reach of the waves. The sea was unusually calm that day. Far away, a group of birds moved together across the horizon, changing direction whenever the wind shifted. A boy walked along the beach collecting shells and pieces of smooth glass. He placed each discovery carefully into a blue bucket, although he had no plan for what to do with them later. His grandfather sat nearby beneath a faded umbrella and watched without saying much. Occasionally he pointed toward something floating in the water, and the boy would run closer to investigate. By afternoon, the bucket was nearly full. The boy looked at his collection proudly, then suddenly decided that he liked the beach better without it. One by one, he returned the shells to the sand. The glass pieces stayed in his pocket. Some things, he decided, were worth keeping."]},"scope":{"from":92,"to":178}}'::jsonb, '[{"kind":"highlight","color":"#ff0000"}]'::jsonb);

  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('1b9c1b54-1b4d-4670-86fe-accf34300f00', 'ae238f44-6cc5-48b7-a991-daf82ea70f79', 14, 'word', 'Font Colour', 'Easy', 3,
    'Change the text colour of paragraph to Red.', 'पैराग्राफ के text को red colour करें।',
    ARRAY['Select the whole paragraph — drag across it, or click Select All in the Editing group.', 'In the Font group, open the arrow beside Font Colour.', 'Pick red from the palette.']::text[], ARRAY['पूरे पैराग्राफ को सेलेक्ट करें — उस पर ड्रैग करें, या Editing ग्रुप में Select All पर क्लिक करें।', 'Font ग्रुप में Font Colour के बगल वाले तीर को खोलें।', 'पैलेट में से लाल चुनें।']::text[],
    '{"subject":"word","lines":{"en":["Rain arrived without warning just after lunch, tapping softly against windows and turning the dusty road outside into a ribbon of silver. People hurried beneath umbrellas, while a few stood under shop awnings waiting for the clouds to pass. An old man carried a paper bag filled with vegetables, carefully balancing it beneath his coat. Across the street, a dog shook water from its fur and looked offended by the weather. Inside a small café, three friends continued their conversation as though the storm were part of the furniture. Steam rose from cups of tea, and someone played a quiet song from a phone near the counter. The rain became heavier for a while, covering every other sound in the neighborhood. Then, almost as suddenly as it had begun, it weakened. The clouds opened slightly, allowing a thin beam of sunlight to fall across the wet pavement. Cars moved again, bicycles appeared, and the street slowly returned to its usual rhythm. Nobody remembered exactly what they had been rushing toward, but everyone seemed happier to be moving again."],"hi":["Rain arrived without warning just after lunch, tapping softly against windows and turning the dusty road outside into a ribbon of silver. People hurried beneath umbrellas, while a few stood under shop awnings waiting for the clouds to pass. An old man carried a paper bag filled with vegetables, carefully balancing it beneath his coat. Across the street, a dog shook water from its fur and looked offended by the weather. Inside a small café, three friends continued their conversation as though the storm were part of the furniture. Steam rose from cups of tea, and someone played a quiet song from a phone near the counter. The rain became heavier for a while, covering every other sound in the neighborhood. Then, almost as suddenly as it had begun, it weakened. The clouds opened slightly, allowing a thin beam of sunlight to fall across the wet pavement. Cars moved again, bicycles appeared, and the street slowly returned to its usual rhythm. Nobody remembered exactly what they had been rushing toward, but everyone seemed happier to be moving again."]},"scope":"all"}'::jsonb, '[{"kind":"fontColor","color":"#ff0000"}]'::jsonb);

