  INSERT INTO test_questions
    (id, test_id, position, subject, topic, difficulty, marks, instruction_en, instruction_hi, solution_en, solution_hi, content, operations)
  VALUES ('9bbb72e4-f052-424e-9ff9-a26ad68b5eed', 'd6c49655-3d70-47bd-bc90-fca05effdffc', 5, 'excel', 'Currency Format & Background', 'Medium', 3,
    'Apply Currency with no decimal places to D2:D6, and set the cell background to Orange.', 'D2:D6 को Currency (बिना Decimal) में Format करें तथा Cell Background Orange करें।',
